2	import java.util.List;
3	import java.util.Random;
4	
5	/**
6	 * An actor is a representation of a living thing in the simulation.
7	 *
8	 * @version 2022.03.01
9	 */
10	public abstract class Actor 
11	{
12	    // The actor's field.
13	    private Field field;
14	    // The actor's position in the field.
15	    private Location location;
16	    // Whether the actor is alive or not.
17	    private boolean alive;
18	    //The actor's age
19	    private int age;
20	    //how much the actor grows. This is added to the animals food level.
21	    private double growthLevel;
22	    // A shared random number generator to control breeding.
23	    private static final Random rand = Randomizer.getRandom();
24	    /**
25	     * Create a new actor at location in field.
26	     * 
27	     * @param field The field currently occupied.
28	     * @param location The location within the field.
29	     */
30	    public Actor(Field field, Location location)
31	    {
32	        this.field = field;
33	        setLocation(location);
34	        alive = true;
35	    }
36	
37	    /**
38	     * Return the actor's location.
39	     * @return The actors's location.
40	     */
41	    protected Location getLocation()
42	    {
43	        return location;
44	    }
45	
46	    /**
47	     * Place the actor at the new location in the given field.
48	     * @param newLocation The actor's new location.
49	     */
50	    protected void setLocation(Location newLocation)
51	    {
52	        if(location != null) {
53	            field.clear(location);
54	        }
55	        location = newLocation;
56	        field.place(this, newLocation);
57	    }
58	
59	    /**
60	     * Return the actors's field.
61	     * @return The actors's field.
62	     */
63	    protected Field getField()
64	    {
65	        return field;
66	    }
67	
68	    /**
69	     * Set the field.
70	     * @param place. The field.
71	     */
72	    protected void setField(Field place){
73	        field = place;
74	    }
75	
76	    /**
77	     * Check whether the actor is alive or not.
78	     * @return true if the actor is still alive.
79	     */
80	    protected boolean isActive()
81	    {
82	        return alive;
83	    }
84	
85	    /**
86	     * Set if the actor is alive or not.
87	     * @param alive. If the actor is alive.
88	     */
89	    protected void setAlive(boolean alive)
90	    {
91	        this.alive = alive;
92	    }
93	
94	    /**
95	     * Indicate that the actor is no longer alive.
96	     * It is removed from the field.
97	     */
98	    protected void setDead()
99	    {
100	        setAlive(false);
101	        if(getLocation() != null) {
102	            getField().clear(getLocation());
103	            location = null ;
104	            field = null;
105	        }
106	    }
107	
108	    /**
109	     * Make this actor act - that is: make it do
110	     * whatever it wants/needs to do.
111	     * @param newActors A list to receive newly born actors.
112	     * @param simulator The simulator.
113	     */
114	    public abstract void act(List<Actor> newActors, Simulator simulator);
115	
116	    /**
117	     * Get age of an actor
118	     * @return age of the actor.
119	     */
120	    protected int getAge(){
121	        return age;
122	    }
123	
124	    /**
125	     * Set age of an actor
126	     * @param age. Age of the actor.
127	     */
128	    protected void setAge(int  age){
129	        this.age = age ;
130	    }
131	
132	    /**
133	     * Increase the age. This could result in the actor's death.
134	     * Actor's age only increases once every 4 steps.
135	     * @param step. The number of steps in the simulation
136	     */
137	    protected void incrementAge(int step)
138	    {
139	        if(step % 4 == 0){
140	            age++;
141	        }
142	        if(age > getMaxAge()) {
143	            setDead();
144	        }
145	    }
146	
147	    /**
148	     * Gets the max age of an actor.
149	     * @return Max age of the actor.
150	     */
151	    abstract protected int getMaxAge();
152	
153	    /**
154	     * Return how much the actor has grown.
155	     * @return  How much the actor grows.
156	     */
157	    protected double getGrowthLevel(){
158	        return growthLevel;
159	    }
160	
161	    /**
162	     * Increase the actor growth level by how much the actor has grown during this step.
163	     * @param value. How much more the actor has grown.
164	     */
165	    protected void setGrowthLevel(double value){
166	        growthLevel = value + growthLevel;
167	    }
168	    
169	    /**
170	     * Returns the shared random generator object
171	     * @return The random generator object
172	     */
173	    protected Random getRandom(){
174	        return rand;
175	    }
176	}

