2	import java.util.List;
3	import java.util.Random;
4	import java.util.Iterator;
5	import java.util.HashMap;
6	
7	/**
8	 * A class representing shared characteristics of animals.
9	 *
10	 * @version 2022.03.01
11	 */
12	public abstract class Animal extends Actor
13	{
14	    private double foodLevel;
15	    private boolean isGirl;
16	    private boolean isHealthy;
17	    //the number of steps an animal takes when infected.
18	    private int infectedStepCounter;
19	    //how many steps animal needs to wait before it can breed again.
20	    private int timeLeftUntilBreedingAgain = 0;
21	    /**
22	     * Create a new animal at location in field.
23	     * 
24	     * @param field The field currently occupied.
25	     * @param location The location within the field.
26	     */
27	    public Animal(Field field, Location location)
28	    {
29	        super(field,location);
30	        setRandomGender();
31	        isHealthy = true;
32	        infectedStepCounter = 0;
33	        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
34	        if(!isGirl){
35	        timeLeftUntilBreedingAgain = 0;
36	        }
37	    }
38	
39	    /**
40	     * Make this animal act - that is: make it do
41	     * whatever it wants/needs to do.
42	     * @param newAnimals A list to receive newly born animals.
43	     * @param simulator The simulator.
44	     */
45	    public void act(List<Actor> newAnimals, Simulator simulator){
46	        Location newLocation = null;
47	        switch(simulator.getWeather()){
48	            case SUNNY:
49	                newLocation = findFood(getSunnyFindingFoodProbability());
50	                break;
51	            case RAINY:
52	                newLocation = findFood(getRainyFindingFoodProbability());
53	                break;
54	            case FOGGY:
55	                newLocation = findFood(getFoggyFindingFoodProbability());
56	                break;
57	            default:
58	                findFood(getRandom().nextDouble());
59	                break;
60	        }
61	        if(newLocation == null) { 
62	            // No food found - try to move to a free location.
63	            newLocation = getField().freeAdjacentLocation(getLocation());
64	        }
65	        if(newLocation != null) {
66	            setLocation(newLocation);
67	        }
68	        else {
69	            // Overcrowding.
70	            setDead();
71	        }
72	    }
73	
74	    /**
75	     * An animal can breed if it has reached the breeding age.
76	     * @return true if an animal is able to breed
77	     */
78	    protected boolean canBreed()
79	    {
80	        return getAge() >= getBreedingAge();
81	    }
82	
83	    /**
84	     * Get breeding age of an animal.
85	     * @return int. Breeding age of the animal;
86	     */
87	    abstract protected int getBreedingAge();
88	
89	    /**
90	     * Check whether or not this animal is to give birth at this step.
91	     * New births will be made into free adjacent locations.
92	     * @param newAnimals A list to return newly born animals.
93	     */
94	    protected void giveBirth(List<Actor> newAnimals)
95	    {
96	        // New animals are born into adjacent locations.
97	        // Get a list of adjacent free locations.
98	        Field field = getField();
99	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
100	        if (timeLeftUntilBreedingAgain != 0){
101	            timeLeftUntilBreedingAgain --;
102	        }
103	        int births = breed();
104	        for(int b = 0; b < births && free.size() > 0; b++) {
105	            Location loc = free.remove(0);
106	            Animal young = getAnimal();
107	            Animal baby = null;
108	            if(young instanceof Gazelle){
109	                baby = new Gazelle(false, field, loc);
110	            }else if(young instanceof Jaguar){
111	                baby = new Jaguar(false, field, loc);
112	            }else if(young instanceof Cheetah){
113	                baby = new Cheetah(false, field, loc);
114	            }else if(young instanceof Lion){
115	                baby = new Lion(false, field, loc);
116	            }else if(young instanceof Zebra){
117	                baby = new Zebra(false, field, loc);
118	            }
119	            if(!getHealth()){
120	                baby.setUnhealthy(); //setting the baby to be unhealthy if the parent is unhealthy.
121	            }
122	            newAnimals.add(baby);
123	        }
124	    }
125	
126	    /**
127	     * Generate a number representing the number of births,
128	     * if it can breed.
129	     * Females can mate with a male even  regardless of the males breeding time .
130	     * @return The number of births (may be zero).
131	     */
132	    protected int breed()
133	    {
134	        int births = 0;
135	        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
136	            births = getRandom().nextInt(getMaxLitterSize()) + 1;
137	            timeLeftUntilBreedingAgain = getMaxTimeUntilBreedingAgain();
138	        }
139	        return births;
140	    }
141	
142	    /**
143	     * If the animal can find a mate of the opposite gender that can breed, true is returned.
144	     * @return true if the animal can find a mate.
145	     */
146	    protected boolean findMate()
147	    {
148	        Field field = getField();
149	        List<Location> adjacent = field.adjacentLocations(getLocation());
150	        Iterator<Location> it = adjacent.iterator();
151	        Animal currentAnimal = getAnimal();
152	        while(it.hasNext()) {
153	            Location where = it.next();
154	            Object animal = field.getObjectAt(where);
155	            if (animal != null && animal.getClass() == currentAnimal.getClass()){
156	                Animal mate = (Animal) animal;
157	                if(isActive() && currentAnimal.getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
158	                    if(!currentAnimal.getHealth() || !mate.getHealth()){
159	                        currentAnimal.setUnhealthy();
160	                        mate.setUnhealthy();
161	                    }
162	                    return true;
163	                }
164	            }
165	        }
166	        return false;
167	    }
168	
169	    /**
170	     * Returns the breeding probability of the animal
171	     * @return breeding probability of the animal.
172	     */
173	    abstract protected double getBreedingProbability();
174	
175	    /**
176	     * Returns the maximum number of babies the animal can give birth to at once.
177	     * @return max litter size of the animal.
178	     */
179	    abstract protected int getMaxLitterSize();
180	
181	    /**
182	     * Returns the current animal occupying the location.
183	     * @return the current animal.
184	     */
185	    abstract protected Animal getAnimal();
186	
187	    /**
188	     * Returns the animal's current food level.
189	     * @return the animal's food level.
190	     */
191	    protected double getFoodLevel(){
192	        return foodLevel;
193	    }
194	
195	    /**
196	     * Sets the animal's food level.
197	     * @param food level The amount of food the animal gets.
198	     */
199	    protected void setFoodLevel(double foodlevel){
200	        this.foodLevel += foodlevel ; 
201	    }
202	
203	    /**
204	     * Make this animal more hungry. This could result in the animal's death.
205	     */
206	    protected void incrementHunger()
207	    {
208	        foodLevel--;
209	        if(foodLevel <= 0) {
210	            setDead();
211	        }
212	    }
213	
214	    /**
215	     * Look for preys adjacent to the current location.
216	     * Only the first live prey is eaten.
217	     * @param probability The probability the animal finds prey.
218	     * @return Where food was found, or null if it wasn't.
219	     */
220	    protected Location findFood(double probability)
221	    {
222	
223	        Field field = getField();
224	        List<Location> adjacent = field.adjacentLocations(getLocation());
225	        Iterator<Location> it = adjacent.iterator();
226	       
227	        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
228	            while(it.hasNext()) {
229	                Location where = it.next();
230	                Object animal = field.getObjectAt(where);
231	                if(animal != null && animal  instanceof Actor){
232	                    Actor currentAnimal = (Actor) animal;
233	                    for(Actor prey: getFood().keySet())
234	                    {
235	                        if(prey.getClass() == currentAnimal.getClass()){
236	                            if (currentAnimal instanceof Animal){
237	                                Animal current = (Animal)currentAnimal;
238	                                if(!current.getHealth()){
239	                                    setUnhealthy();
240	                                }
241	                            }
242	                            currentAnimal.setDead();
243	                            setFoodLevel(getFood().get(prey)  + currentAnimal.getGrowthLevel());
244	                            if(getFoodLevel() > getMaxFoodLevel()){
245	                                setFoodLevel(getMaxFoodLevel() - getFoodLevel());
246	                            }
247	                            return where;
248	                        }
249	                    }
250	                }
251	            }
252	        }
253	        return null;
254	    }
255	
256	    /**
257	     * Returns the HashMap which contains what prey the animal eats and the amount of food each prey gives.
258	     * @return The HashMap which contains the Actor and an Integer.
259	     */
260	    abstract protected HashMap<Actor, Integer> getFood();
261	
262	    /**
263	     * Uses a random generator to assign if the animal is female or not.
264	     * @return True if the animal is a female.
265	     */
266	    protected void setRandomGender(){
267	        isGirl = getRandom().nextDouble() > 0.5;
268	    }
269	
270	    /**
271	     * Returns true if the animal is a female.
272	     * @return boolean. True if the animal is a female.
273	     */
274	    protected boolean getIsGirl(){
275	        return isGirl;
276	    }
277	
278	    /**
279	     * The animal has been infected.
280	     */
281	    protected void setUnhealthy(){
282	        isHealthy = false;
283	    }
284	
285	    /**
286	     * Returns whether the animal is healthy or not.
287	     * @return true if the animal is healthy.
288	     */
289	    protected boolean getHealth(){
290	        return isHealthy;
291	    }
292	
293	    /**
294	     * Increase the age. This could result in the animal's death.
295	     * If the animal is unhealthy it also increases the infected step counter.
296	     * After 5 steps inthe infectedStepCounter this may result in the animal's death.
297	     * @param step. The number of steps in the simulation.
298	     */
299	    protected void incrementAge(int step)
300	    {
301	        super.incrementAge(step);
302	        if(!getHealth()){
303	            infectedStepCounter++;}
304	
305	        if(infectedStepCounter == 5) {
306	            setDead();
307	        }
308	    }
309	
310	    /**
311	     * Gets the max food level of an animal.
312	     * @return Maximum food level of the current animal.
313	     */
314	    abstract protected double getMaxFoodLevel();
315	
316	    /**
317	     * Gets the max time an animal needs to wait before it can breed again.
318	     * @return Maximum time the animal waits before it can breed again.
319	     */
320	    abstract protected int getMaxTimeUntilBreedingAgain();
321	
322	    /**
323	     * Gets the probability the animal will find food when it is sunny
324	     * @return The probability the animal will find food when it is sunny
325	     */
326	    abstract protected double getSunnyFindingFoodProbability();
327	
328	    /**
329	     * Gets the probability the animal will find food when it is rainy
330	     * @return The probability the animal will find food when it is rainy
331	     */
332	    abstract protected double getRainyFindingFoodProbability();
333	
334	    /**
335	     * Gets the probability the animal will find food when it is foggy
336	     * @return The probability the animal will find food when it is foggy
337	     */
338	    abstract protected double getFoggyFindingFoodProbability();
339	}
