5	/**
6	 * A class representing additional characteristics for predators.
7	 * Inlucdes an additional method for carnivores which allow them to step
8	 * on the grass without eating it.
9	 *
10	 * @version 2022.03.01
11	 */
12	public abstract class Predator extends Animal
13	{
14	
15	    /**
16	     * Create a new predator at location in field.
17	     * 
18	     * @param field The field currently occupied.
19	     * @param location The location within the field.
20	     *
21	     */public Predator(Field field, Location location){
22	        super(field, location);
23	    }
24	
25	    /**
26	     * If food is not found then the animal moves towards the nearest plant.
27	     * It does not eat the plant, instead stands on top of it.
28	     * @param probability The probability the animal finds prey.
29	     * @return Where plant was found, or null if it wasn't.
30	     */
31	    protected Location findFood(double probability)
32	    {
33	        if (super.findFood(probability) == null){
34	            Field field = getField();
35	            List<Location> adjacent = field.adjacentLocations(getLocation());
36	            Iterator<Location> it = adjacent.iterator();
37	            while(it.hasNext()) {
38	                Location where = it.next();
39	                Object actor = field.getObjectAt(where);
40	                if(actor != null && actor  instanceof Plants){
41	                    return where;
42	                }
43	            }
44	        }
45	        return null;
46	    }
47	}
