1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	
7	/**
8	 * A simple predator-prey simulator of a safari, based on a rectangular field
9	 * containing lions, cheetahs, jaguars, zebras, gazelles, hunters and grass.
10	 *
11	 * @version 2022.03.01
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation.
16	    // The default width for the grid.
17	    private static final int DEFAULT_WIDTH = 175;
18	    // The default depth of the grid.
19	    private static final int DEFAULT_DEPTH = 150;
20	
21	    // The probability that each actor will be created in any given grid position.
22	    private static final double JAGUAR_CREATION_PROBABILITY = 0.011; 
23	    private static final double GAZELLE_CREATION_PROBABILITY = 0.2;
24	    private static final double LION_CREATION_PROBABILITY = 0.017 ; 
25	    private static final double PLANT_CREATION_PROBABILITY = 0.55; 
26	    private static final double CHEETAH_CREATION_PROBABILITY =0.032;
27	    private static final double ZEBRA_CREATION_PROBABILITY = 0.4998; 
28	    private static final double HUNTER_CREATION_PROBABILITY = 0.01; 
29	
30	    // List of animals and plants which can not be stood on in the field.
31	    private List<Actor> animals;
32	    // List of plants that can be stood on in the field.
33	    private List<Actor> plants;
34	    // The current state of the field.
35	    private Field field;
36	    // The current step of the simulation.
37	    private int step;
38	    // A graphical view of the simulation.
39	    private SimulatorView view;
40	
41	    private boolean isDay;
42	    //check the random weather method and the use of the random weather method in one step method
43	    private Weather weather;
44	    private int numberOfDays;
45	    private static final Random rand = Randomizer.getRandom();
46	    private int noOfGrass; // keeps count of the no.of grass species in the field.
47	    /**
48	     * Construct a simulation field with default size.
49	     */
50	    public Simulator()
51	    {
52	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
53	    }
54	
55	    /**
56	     * Create a simulation field with the given size.
57	     * @param depth Depth of the field. Must be greater than zero.
58	     * @param width Width of the field. Must be greater than zero.
59	     */
60	    public Simulator(int depth, int width)
61	    {
62	        if(width <= 0 || depth <= 0) {
63	            System.out.println("The dimensions must be greater than zero.");
64	            System.out.println("Using default values.");
65	            depth = DEFAULT_DEPTH;
66	            width = DEFAULT_WIDTH;
67	        }
68	
69	        animals = new ArrayList<>();
70	        plants = new ArrayList<>();
71	        field = new Field(depth, width);
72	
73	        // Create a view of the state of each location in the field.
74	        view = new SimulatorView(depth, width, this);
75	        view.setColor(Gazelle.class, Color.ORANGE);
76	        view.setColor(Jaguar.class, Color.BLUE);
77	        view.setColor(Cheetah.class, Color.RED);
78	        view.setColor(Lion.class, Color.PINK);
79	        view.setColor(Grass.class, Color.GREEN);
80	        view.setColor(Zebra.class, Color.BLACK);
81	        view.setColor(Hunter.class, Color.MAGENTA);
82	        // Setup a valid starting point.
83	        reset();
84	    }
85	
86	    /**
87	     * Run the simulation from its current state for a reasonably long period,
88	     * (4000 steps).
89	     */
90	    public void runLongSimulation()
91	    {
92	        simulate(4000);
93	    }
94	
95	    /**
96	     * Run the simulation from its current state for the given number of steps.
97	     * Stop before the given number of steps if it ceases to be viable.
98	     * @param numSteps The number of steps to run for.
99	     */
100	    public void simulate(int numSteps)
101	    {
102	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
103	            simulateOneStep();
104	            //delay(120);   // uncomment this to run more slowly
105	        }
106	    }
107	
108	    /**
109	     * Run the simulation from its current state for a single step.
110	     * Iterate over the whole field updating the state of each
111	     * actor in the field. One  day lasts 4 steps, with day and night alternating every 2 steps.
112	     * Buttons are disabled before the simulation starts and enabled after the simulation is finsihed.
113	     */
114	    public void simulateOneStep()
115	    {
116	        view.disableButton();
117	        step++;
118	        if(step % 2 == 0){
119	            isDay  = !isDay;
120	            if(isDay){
121	                numberOfDays++;
122	            }
123	        }
124	
125	        // Provide space for newborn actors.
126	        List<Actor> newAnimals = new ArrayList<>();  
127	        List<Actor> newGrass = new ArrayList<>();  
128	
129	        getRandomWeather();
130	        while(!isDay && weather == weather.SUNNY){
131	            getRandomWeather();
132	        }
133	        // Let all actors act.
134	        //iterates through all the animals and hunters
135	
136	        for(Iterator<Actor> it = animals.iterator(); it.hasNext(); ) {
137	            Actor animal = it.next();
138	            animal.act(newAnimals,this);
139	            if(! animal.isActive()) {
140	                it.remove();
141	            }
142	        }
143	        animals.addAll(newAnimals);
144	        noOfGrass = 0;
145	        for(Iterator<Actor> it = plants.iterator(); it.hasNext(); ) {
146	            Actor plants = it.next();
147	            plants.act(newGrass,this);
148	            if(! plants.isActive()) {
149	                it.remove();
150	            }else if(plants instanceof Plants){
151	                noOfGrass++;
152	            }
153	        }
154	        plants.addAll(newGrass);
155	
156	        if(step % 500 == 0){
157	            introduceInfection();
158	        }
159	
160	        view.showStatus(field);
161	        view.enableButton();
162	    }
163	
164	    /**
165	     * Reset the simulation to a starting position.
166	     */
167	    public void reset()
168	    {
169	        step = 0;
170	        animals.clear();
171	        plants.clear();
172	        populate();
173	        isDay = true;
174	        numberOfDays = 0;
175	        getRandomWeather();
176	        // Show the starting state in the view.
177	        view.showStatus(field);
178	    }
179	
180	    /**
181	     * Randomly populate the field with all the actors.
182	     */
183	    private void populate()
184	    {
185	        //Random rand = Randomizer.getRandom();
186	        field.clear();
187	        for(int row = 0; row < field.getDepth(); row++) {
188	            for(int col = 0; col < field.getWidth(); col++) {
189	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
190	                    Location location = new Location(row, col);
191	                    Animal lion = new Lion(true, field, location);
192	                    animals.add(lion);
193	                }
194	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
195	                    Location location = new Location(row, col);
196	                    Animal cheetah = new Cheetah(true, field, location);
197	                    animals.add(cheetah);
198	                }
199	                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
200	                    Location location = new Location(row, col);
201	                    Animal gazelle = new Gazelle(true, field, location);
202	                    animals.add(gazelle);
203	                }else if(rand.nextDouble() <= JAGUAR_CREATION_PROBABILITY) {
204	                    Location location = new Location(row, col);
205	                    Animal jaguar = new Jaguar(true, field, location);
206	                    animals.add(jaguar);
207	                }else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
208	                    Location location = new Location(row, col);
209	                    Plants grass = new Grass(true, field, location);
210	                    plants.add(grass);
211	                }
212	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
213	                    Location location = new Location(row, col);
214	                    Animal zebra = new Zebra(true, field, location);
215	                    animals.add(zebra);
216	                }else if(rand.nextDouble() <= HUNTER_CREATION_PROBABILITY) {
217	                    Location location = new Location(row, col);
218	                    Hunter hunter = new Hunter(field, location);
219	                    animals.add(hunter);
220	                }
221	                // else leave the location empty.
222	            }
223	        }
224	    }
225	
226	    /**
227	     * Pause for a given time.
228	     * @param millisec  The time to pause for, in milliseconds
229	     */
230	    private void delay(int millisec)
231	    {
232	        try {
233	            Thread.sleep(millisec);
234	        }
235	        catch (InterruptedException ie) {
236	            // wake up
237	        }
238	    }
239	
240	    /**
241	     * Return the total number of steps the simulation has run for.
242	     * @return The total steps the simualtion ran for.
243	     */
244	    public int getSteps(){
245	        return step;
246	    }
247	
248	    /**
249	     * Randomly generates a weather from the enum class.
250	     * @return A random weather.
251	     */
252	    private void getRandomWeather(){
253	        int value = rand.nextInt(weather.values().length);
254	        weather = weather.values()[value];
255	    }
256	
257	    /**
258	     * Returns the List which contains all the plants in the simualtion.
259	     * @return A list of all the alive plants in the simulation.
260	     */
261	    public List<Actor> getGrass(){
262	        return plants;
263	    }  
264	
265	    /**
266	     * Chooses a random animal to infect. This method is automatically called after 100 steps,
267	     * or it can be called by pressing the introduce infection button.
268	     */
269	    public void introduceInfection(){
270	        if(animals.size() != 0){
271	            int value = rand.nextInt(animals.size());
272	            if(animals.get(value) instanceof Animal){
273	                Animal animal = (Animal)animals.get(value);
274	                animal.setUnhealthy();
275	            }
276	        }
277	    }
278	    
279	    /**
280	     * Returns the number of grass in the plants arrayList.
281	     * @return number of grass in arraylist.
282	     */
283	    public int getNoOfGrass(){
284	        return noOfGrass;
285	    }
286	    
287	    /**
288	     * Returns the number of days.
289	     * @return  number of days.
290	     */
291	    public int  getNoOfDays(){
292	        return numberOfDays;
293	    }
294	    
295	    /**
296	     * Returns if it is currently day or night.
297	     * @return true if it is day.
298	     */
299	    public boolean  isDay(){
300	        return isDay;
301	    }
302	    
303	    /**
304	     * Return the weather in the simulation.
305	     * @return weather The current weather in the simulation.
306	     */
307	    public Weather getWeather(){
308	        return weather;
309	    }
310	}
