2	import java.util.Iterator;
3	import java.util.List;
4	import java.util.Random;
5	
6	/**
7	 * A simple model of a Hunter.
8	 * Hunters age, move, hunt lions, and die.
9	 * Hunters can bring other hunters after 898 steps to increse the hunter population.
10	 *
11	 * @version 2022.03.01
12	 */
13	public class Hunter extends Actor
14	
15	{
16	    // Characteristics shared by all Hunters.
17	    private static final int MAX_AGE = 1000;
18	    private static final int SHOTS = 2; 
19	    /**
20	     * Create a Hunter. A hunter is created as an adult (age 50).
21	     * 
22	     * @param field The field currently occupied.
23	     * @param location The location within the field.
24	     */
25	    public Hunter(Field field, Location location)
26	    {
27	        super(field, location);
28	        setAge(50);
29	        setGrowthLevel(0);
30	    }
31	
32	    /**
33	     * This is what the Hunter does most of the time: it hunts
34	     * lions during the night. In the process, it might die of old age.
35	     * 
36	     * @param newHunters A list to return new Hunters.
37	     * @param simulator The simulator.
38	     */
39	    public void act(List<Actor> newHunters,Simulator simulator){
40	        incrementAge(simulator.getSteps());
41	        if(!simulator.isDay()){
42	            if(isActive() ) {
43	                switch(simulator.getWeather()){
44	                    case RAINY:
45	                        hunt(0.7);
46	                        break;
47	                    case FOGGY:
48	                        hunt(0.4);
49	                        break;
50	                    default:
51	                        hunt(getRandom().nextDouble());
52	                        break;
53	                }
54	                Field field = getField();
55	                Location newLocation = field.freeAdjacentLocation(getLocation());
56	                if(newLocation != null) {
57	                    setLocation(newLocation);
58	                } 
59	                //hunter number increases as there are more hunters in the area who want to hunt.
60	                if (simulator.getSteps() % 898 ==  0){
61	                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
62	                    if(free.size() > 0) {
63	                        Location loc = free.remove(0);
64	                        Hunter hunter = new Hunter(field, loc);
65	                        newHunters.add(hunter);
66	                    }
67	                }
68	            }
69	        }
70	    }
71	
72	    /**
73	     * This determine how the hunter hunts nearby lions
74	     * The hunter has 2 shots.
75	     * @param probability The probability the hunting is successful.
76	     */
77	    private void hunt(double probability){
78	        if(getRandom().nextDouble() < probability){
79	            Field field = getField();
80	            List<Location> adjacent = field.adjacentLocations(getLocation());
81	            Iterator<Location> it = adjacent.iterator();
82	            for(int i = 0; i< SHOTS; i++){
83	                Location where = it.next();
84	                Object animal = field.getObjectAt(where);
85	                if( animal != null && (animal instanceof Lion  || animal instanceof Cheetah)){
86	                    Animal currentAnimal = (Animal) animal;
87	                    if(currentAnimal.isActive()) { 
88	                        currentAnimal.setDead();
89	                        break;
90	                    }
91	                }
92	            }
93	        }
94	    }
95	
96	    /**
97	     * Gets the max age of a hunter.
98	     * @return int. Max age of the hunter.
99	     */
100	    protected int getMaxAge(){
101	        return MAX_AGE;
102	    }
103	}
