62	    /**
63	     * Randomly generates minutes.
64	     * @return minutes as a string.
65	     */
66	    public String getMinutes(){
67	        int min = random.nextInt(60);
68	        minutes = Integer.toString(min);
69	        if(min < 10){
70	            minutes = "0" + minutes;
71	        }
72	        return minutes;
