75	    /**
76	     * Uses the step number to decide what time of day it is to randomly generate an apporopriate time.
77	     * @param steps. The step number currently in the simulation.
78	     * @return Current time in the simualtion.
79	     */
80	    public String getTime(int steps){
81	        int value = steps % 4;
82	        if(value == 0){
