import java.util.List;
import java.util.Random;
import java.util.Iterator;
import java.util.HashMap;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.01
 */
public abstract class Animal extends Actor
{
    private double foodLevel;
    private boolean isGirl;
    private boolean isHealthy;
    //the number of steps an animal takes when infected.
    private int infectedStepCounter;
    //how many steps animal needs to wait before it can breed again.
    private int timeLeftUntilBreedingAgain = 0;
    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        super(field,location);
        setRandomGender();
        isHealthy = true;
        infectedStepCounter = 0;
        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
        if(!isGirl){
        timeLeftUntilBreedingAgain = 0;
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newAnimals, Simulator simulator){
        Location newLocation = null;
        switch(simulator.getWeather()){
            case SUNNY:
                newLocation = findFood(getSunnyFindingFoodProbability());
                break;
            case RAINY:
                newLocation = findFood(getRainyFindingFoodProbability());
                break;
            case FOGGY:
                newLocation = findFood(getFoggyFindingFoodProbability());
                break;
            default:
                findFood(getRandom().nextDouble());
                break;
        }
        if(newLocation == null) { 
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
        }
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * An animal can breed if it has reached the breeding age.
     * @return true if an animal is able to breed
     */
    protected boolean canBreed()
    {
        return getAge() >= getBreedingAge();
    }

    /**
     * Get breeding age of an animal.
     * @return int. Breeding age of the animal;
     */
    abstract protected int getBreedingAge();

    /**
     * Check whether or not this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        if (timeLeftUntilBreedingAgain != 0){
            timeLeftUntilBreedingAgain --;
        }
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Animal baby = createOffspring(field, loc);
            if(!getHealth()){
                baby.setUnhealthy();
            }
            newAnimals.add(baby);
        }
    }

    abstract protected Animal createOffspring(Field field, Location location);

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * Females can mate with a male even  regardless of the males breeding time .
     * @return The number of births (may be zero).
     */
    protected int breed()
    {
        int births = 0;
        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
            births = getRandom().nextInt(getMaxLitterSize()) + 1;
            timeLeftUntilBreedingAgain = getMaxTimeUntilBreedingAgain();
        }
        return births;
    }

    /**
     * If the animal can find a mate of the opposite gender that can breed, true is returned.
     * @return true if the animal can find a mate.
     */
    protected boolean findMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal != null && animal.getClass() == this.getClass()){
                Animal mate = (Animal) animal;
                if(isActive() && getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
                    if(!getHealth() || !mate.getHealth()){
                        setUnhealthy();
                        mate.setUnhealthy();
                    }
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns the breeding probability of the animal
     * @return breeding probability of the animal.
     */
    abstract protected double getBreedingProbability();

    /**
     * Returns the maximum number of babies the animal can give birth to at once.
     * @return max litter size of the animal.
     */
    abstract protected int getMaxLitterSize();

    /**
     * Returns the animal's current food level.
     * @return the animal's food level.
     */
    protected double getFoodLevel(){
        return foodLevel;
    }

    /**
     * Sets the animal's food level.
     * @param food level The amount of food the animal gets.
     */
    protected void setFoodLevel(double foodlevel){
        this.foodLevel += foodlevel ; 
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Look for preys adjacent to the current location.
     * Only the first live prey is eaten.
     * @param probability The probability the animal finds prey.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(double probability)
    {

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
            while(it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if(animal instanceof Actor){
                    Actor currentAnimal = (Actor) animal;
                    Integer foodValue = getFood().get(currentAnimal.getClass());
                    if(foodValue != null){
                        if (currentAnimal instanceof Animal){
                            Animal current = (Animal)currentAnimal;
                            if(!current.getHealth()){
                                setUnhealthy();
                            }
                        }
                        currentAnimal.setDead();
                        setFoodLevel(foodValue + currentAnimal.getGrowthLevel());
                        if(getFoodLevel() > getMaxFoodLevel()){
                            setFoodLevel(getMaxFoodLevel() - getFoodLevel());
                        }
                        return where;
                    }
                }
            }
        }
        return null;
    }

    /**
     * Returns the HashMap which contains what prey the animal eats and the amount of food each prey gives.
     * @return The HashMap which contains the Actor and an Integer.
     */
    abstract protected HashMap<Actor, Integer> getFood();

    /**
     * Uses a random generator to assign if the animal is female or not.
     * @return True if the animal is a female.
     */
    protected void setRandomGender(){
        isGirl = getRandom().nextDouble() > 0.5;
    }

    /**
     * Returns true if the animal is a female.
     * @return boolean. True if the animal is a female.
     */
    protected boolean getIsGirl(){
        return isGirl;
    }

    /**
     * The animal has been infected.
     */
    protected void setUnhealthy(){
        isHealthy = false;
    }

    /**
     * Returns whether the animal is healthy or not.
     * @return true if the animal is healthy.
     */
    protected boolean getHealth(){
        return isHealthy;
    }

    /**
     * Increase the age. This could result in the animal's death.
     * If the animal is unhealthy it also increases the infected step counter.
     * After 5 steps inthe infectedStepCounter this may result in the animal's death.
     * @param step. The number of steps in the simulation.
     */
    protected void incrementAge(int step)
    {
        super.incrementAge(step);
        if(!getHealth()){
            infectedStepCounter++;}

        if(infectedStepCounter == 5) {
            setDead();
        }
    }

    /**
     * Gets the max food level of an animal.
     * @return Maximum food level of the current animal.
     */
    abstract protected double getMaxFoodLevel();

    /**
     * Gets the max time an animal needs to wait before it can breed again.
     * @return Maximum time the animal waits before it can breed again.
     */
    abstract protected int getMaxTimeUntilBreedingAgain();

    /**
     * Gets the probability the animal will find food when it is sunny
     * @return The probability the animal will find food when it is sunny
     */
    abstract protected double getSunnyFindingFoodProbability();

    /**
     * Gets the probability the animal will find food when it is rainy
     * @return The probability the animal will find food when it is rainy
     */
    abstract protected double getRainyFindingFoodProbability();

    /**
     * Gets the probability the animal will find food when it is foggy
     * @return The probability the animal will find food when it is foggy
     */
    abstract protected double getFoggyFindingFoodProbability();
}

import java.util.List;
import java.util.Random;
import java.util.Iterator;
import java.util.HashMap;

/**
 * A simple model of a Gazelle.
 * Gazelles age, move,eat grass, breed, and die.
 *
 * @version 2022.03.01
 */
public class Gazelle extends Animal
{
    // Characteristics shared by all Gazelles (class variables).

    // The age at which a Gazelle can start to breed.
    private static final int BREEDING_AGE = 2;
    // The age to which a Gazelle can live.
    private static final  int MAX_AGE  = 80;
    // The likelihood of a Gazelle breeding.
    private static final double BREEDING_PROBABILITY = 0.8900995; 
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 7;
    private static final int MAX_TIME_UNTIL_BREEDING_AGAIN = 2;
    //The minimum food value of the grass. In effect, this is the
    // number of steps a Gazelle can go before it has to eat again.
    private static final int GRASS_FOOD_VALUE = 14; //8 //15
    //maximum food a gazelle can eat.
    private static final double MAX_FOOD_LEVEL = 28; //60 //160

    // The likelihood of a Gazelle finding food depending on the weather.
    private static final double SUNNY_FINDING_FOOD_PROBABILITY = 1;
    private static final double RAINY_FINDING_FOOD_PROBABILITY = 1;
    private static final double FOGGY_FINDING_FOOD_PROBABILITY = 1;

    // Individual characteristics (instance fields).
    private HashMap<Actor, Integer> food;
    /**
     * Create a new Gazelle. A Gazelle may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the Gazelle will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Gazelle(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        setAge(0);
        setFoodLevel(GRASS_FOOD_VALUE);
        if(randomAge) {
            setAge(getRandom().nextInt(MAX_AGE));
            setFoodLevel(getRandom().nextInt(GRASS_FOOD_VALUE));
        }
        food = new HashMap<>();
        setGrowthLevel(getAge()/75.0);
        addFood(field);
    }

    /**
     * This is what the Gazelle does most of the time: it finds
     * grass to eat. In the process, it might breed, die of hunger,
     * die of disease or die of old age.
     * 
     * @param newGazelles A list to return newly born Gazelles.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newGazelles, Simulator simulator)
    {
        setGrowthLevel(0.012);
        if(simulator.isDay()){
            incrementAge(simulator.getSteps());
            incrementHunger();
            if(isActive()) {
                giveBirth(newGazelles);  
                super.act(newGazelles,simulator);
            }
        }else{
            //space for potential night activities
        }
    }

    /**
     * Returns the maximum number of babies the gazelle can give birth to at once.
     * @return max litter size of the gazelle.
     */
    protected int getMaxLitterSize(){
        return MAX_LITTER_SIZE;
    }

    /**
     * Returns the breeding probability of the gazelle
     * @return breeding probability of the gazelle.
     */
    protected double getBreedingProbability(){
        return BREEDING_PROBABILITY;
    }

    /**
     * Get breeding age of a gazelle.
     * @return Breeding age of the gazelle;
     */
    protected int getBreedingAge(){
        return BREEDING_AGE;
    }

    /**
     * Gets the max age of a gazelle.
     * @return Max age of the gazelle.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }

    /**
     * Returns the current gazelle occupying the location.
     * @return the current gazelle.
     */
    protected Animal getAnimal(){
        return this;
    }

    /**
     * Adds the food the gazelle eats & the corresponding food value to a hashMap.
     * @param field The field the gazelle is in.
     */
    private void addFood(Field field){
        Location tempLocation = new Location(0,0);
        Plants grass = new Grass(true,field,tempLocation );
        food.put(grass, GRASS_FOOD_VALUE);
        grass.setDead();
    }

    /**
     * Returns the HashMap which contains what food the gazelle eats and the amount of food each plant gives.
     * @return The HashMap which contains the Actor and an Integer.
     */
    protected HashMap<Actor, Integer> getFood(){
        return food;
    }

    /**
     * Gets the maximum food level a gazelle can have.
     * @return Max food level of the gazelle.
     */
    protected double getMaxFoodLevel(){
        return MAX_FOOD_LEVEL;
    }

    /**
     * Gets the maximum time a gazelle needs to wait until it can breed again
     * @return Max time before the gazelle can breed again.
     */
    protected int getMaxTimeUntilBreedingAgain(){
        return MAX_TIME_UNTIL_BREEDING_AGAIN;
    }

    /**
     * Gets the probability the gazelle will find food when it is sunny
     * @return The probability the gazelle will find food when it is sunny
     */
    protected double getSunnyFindingFoodProbability(){
        return SUNNY_FINDING_FOOD_PROBABILITY;
    }

    /**
     * Gets the probability the gazelle will find food when it is rainy
     * @return The probability the gazelle will find food when it is rainy
     */
    protected double getRainyFindingFoodProbability(){
        return RAINY_FINDING_FOOD_PROBABILITY;
    }

    /**
     * Gets the probability the gazelle will find food when it is foggy
     * @return The probability the gazelle will find food when it is foggy
     */
    protected double getFoggyFindingFoodProbability(){
        return FOGGY_FINDING_FOOD_PROBABILITY;
    }
}

